const {test}=require('node:test'),assert=require('node:assert/strict'),L=require('./lesson-engine'),{topicDraft,scenarioDraft}=require('./test-fixtures/interactive-assignment.cjs');
async function assignment(){const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs');let calls=0;const a=await generateCourseAssignment(L,{notes:'You are the bookkeeper for Haslam Company. In 2022, record supplies purchases on account, supplier payments, and supplies used based on a month-end count.',year:2026,month:9,depth:'focused'},{key:'private-test-key',fetcher:async(url,request)=>{calls++;const body=JSON.parse(request.body);if(calls===1){assert.ok(body.messages[1].content.includes('Haslam'));assert.ok(body.response_format.json_schema.schema.properties.topics);}else{assert.ok(!body.messages.map(x=>x.content).join('').includes('Haslam'));assert.ok(!body.messages[1].content.includes('2022'));assert.ok(body.response_format.json_schema.schema.properties.controls);assert.ok(body.messages[0].content.includes('student OWNS'));}return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(calls===1?topicDraft():scenarioDraft())}}]})};}});assert.equal(calls,2);return a;}
test('notes supply topics only; original company names, bookkeeper roles, dates and amounts do not reach the scenario writer',async()=>{const a=await assignment();assert.ok(a.interactive);assert.equal(L.checkAssignment(a),true);assert.ok(!a.instructions.includes('Haslam'));assert.ok(!a.instructions.includes('bookkeeper'));});
test('student quantities set invoice totals, payments, month-end counts, and journal answers rather than selecting preset plans',async()=>{const a=await assignment(),b={name:'Tommy’s Coffee',type:'Coffee shop'},choice=L.decisions.defaultChoice(a,b);choice.decision1={beans:4,cups:3,filters:0};choice.decision2=25;const s=L.expected(a,choice,b),purchase=s.events.find(e=>e.id==='supplies-invoice'),payment=s.events.find(e=>e.id==='supplier-payment'),count=s.events.find(e=>e.id==='supplies-count');assert.equal(purchase.lines[0].debit,234);assert.equal(payment.lines[0].debit,58.5);assert.equal(count.lines[0].debit,140.4);assert.ok(purchase.detail.document.fields.some(x=>x.value.includes('4 × Coffee beans')));assert.ok(count.detail.document.fields.some(x=>x.value==='$93.60'));choice.decision1.beans=8;assert.equal(L.expected(a,choice,b).events.find(e=>e.id==='supplies-invoice').lines[0].debit,414);});
test('the same assignment uses relevant items and fresh amounts for different semester businesses',async()=>{const a=await assignment();for(const type of Object.keys(L.businesses)){const b={name:'My '+type,type},choice=L.decisions.defaultChoice(a,b),s=L.expected(a,choice,b),invoice=s.events[0];assert.ok(invoice.detail.document.fields.some(x=>x.value===b.name));assert.ok(!invoice.detail.document.fields.some(x=>x.value.includes('Haslam')));const expectedNames=type==='Cleaning service'?'Cleaning solution':type==='Bakery'?'Flour':type==='Coffee shop'?'Coffee beans':null;if(expectedNames)assert.ok(invoice.detail.document.fields.some(x=>x.value.includes(expectedNames)));assert.ok(s.events.every(e=>L.assess(e.lines,e.date,e).correct));}});
test('zero supplier payment correctly requires no entry, while forged quantities and executable formulas are rejected',async()=>{const a=await assignment(),b={type:'Coffee shop'},choice=L.decisions.defaultChoice(a,b);choice.decision2=0;assert.deepEqual(L.expected(a,choice,b).events.find(e=>e.id==='supplier-payment').lines,[]);choice.decision1.beans=-1;assert.equal(L.decisions.validChoice(a,choice,b),false);choice.decision1.beans=1000;assert.equal(L.decisions.validChoice(a,choice,b),false);choice.decision1.beans=2;choice.decision1.price=1;assert.equal(L.decisions.validChoice(a,choice,b),false);for(const formula of ['globalThis.fetch(1)','decision1.constructor','1/0','missing+2'])assert.throws(()=>L.decisions.calculate(formula,{decision1:200}));});
test('student definitions contain decision inputs, but never the private formulas or answers',async()=>{const a=await assignment(),{studentDefinition,studentRun,changeRun}=await import('./supabase/functions/classroom/service.mjs'),b={name:'Tommy Coffee',type:'Coffee shop'},choice=L.decisions.defaultChoice(a,b),scenario=L.expected(a,choice,b),state={assignment:a,business:b,scenario,choice,stage:0,entries:{},first:{},advanced:false};a.revisionChat=[{role:'user',text:'Private professor request'}];const pub=studentDefinition(a);assert.equal(pub.revisionChat,undefined);assert.ok(pub.interactive.controls.length);assert.equal(pub.interactive.events,undefined);assert.ok(pub.blueprint.paths.every(p=>p.events.every(e=>!e.lines)));const e=scenario.events[0],saved=changeRun(L,state,'entry',{record:e.id,date:e.date,rows:e.lines}),result=studentRun(L,saved);assert.equal(result.assessments[e.id].correct,true);assert.ok(result.scenario.events.every(e=>!e.lines));assert.equal(result.assignment.interactive.events,undefined);});
test('the provider formula schema cannot invent product properties, prices, function calls, or control names',async()=>{const {makeInteractiveSchema}=await import('./supabase/functions/classroom/generation-schema.mjs'),schema=makeInteractiveSchema(2026,11,'focused'),pattern=schema.properties.events.items.properties.lines.items.properties.formula.pattern,re=new RegExp(pattern);assert.equal(schema.properties.events.maxItems,6);for(const expression of ['decision1','decision1*decision2/100','decision1-decision1*decision2/100','decision1*.6'])assert.equal(re.test(expression),true);for(const expression of ['decision1.paper*5','materials*10','Math.round(decision1)','{{decision1}}','decision1.constructor'])assert.equal(re.test(expression),false);});
test('all supporting documents identify the student company without changing suppliers or accounting amounts',async()=>{const a=await assignment(),b={name:'Tommy $& Coffee <Shop>',type:'Coffee shop'},choice=L.decisions.defaultChoice(a,b);for(const token of ['{{business}}','{{business.name}}','{{business_name}}','{{company_name}}','[Business Name]','your company'])assert.equal(L.personalize(token,b),b.name);const s=L.expected(a,choice,b);assert.equal(s.decisions.length,a.interactive.controls.length);assert.ok(s.decisions[0].includes('Coffee beans'));assert.ok(s.decisions[1].includes(String(choice.decision2)));for(const e of s.events){assert.ok(e.detail.document.fields.some(f=>f.label==='Business'&&f.value===b.name));assert.ok(L.assess(e.lines,e.date,e).correct);}const doc=L.personalizeDocument({issuer:'Real Supplier Ltd',status:'Sent to {{company}}',fields:[{label:'Company',value:'Wrong example'},{label:'Customer',value:'Real Customer'}]},b);assert.equal(doc.issuer,'Real Supplier Ltd');assert.equal(doc.fields[0].value,b.name);assert.equal(doc.fields[1].value,'Real Customer');assert.equal(doc.status,'Sent to '+b.name);});
