test('generation repairs missing standard accounts and whitespace/case mismatches before validating and grading',async()=>{const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs');for(const variant of ['missing','case','duplicate']){let calls=0;const made=scenarioDraft();if(variant==='missing')made.accounts=made.accounts.filter(x=>!['Accounts Payable','Supplies Expense'].includes(x.name));if(variant==='case')made.events[0].lines[0].account='  supplies  ';if(variant==='duplicate')made.accounts.push({name:' supplies ',type:'asset'});const a=await generateCourseAssignment(L,{notes:'Supplies purchases, payments to suppliers and closing counts of supplies used.',phase:'review',draft:topicDraft(),year:2026,month:9,depth:'focused'},{key:'test',fetcher:async()=>{calls++;return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(made)}}]})};}});assert.equal(calls,1);assert.equal(L.checkAssignment(a),true);assert.equal(a.blueprint.accounts.filter(x=>x.name==='Supplies').length,1);assert.equal(a.blueprint.accounts.find(x=>x.name==='Supplies Expense').type,'expense');const b={name:'My Coffee',type:'Coffee shop'},s=L.expected(a,L.decisions.defaultChoice(a,b),b);assert.ok(s.events.every(e=>L.assess(e.lines,e.date,e).correct));}});
