test('a follow-up payment date changes the payment and discount while preserving the original order',async()=>{const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs'),{changeRun,studentRun,businessResult}=await import('./supabase/functions/classroom/service.mjs'),{paymentDraft}=require('./test-fixtures/payment-assignment.cjs');let calls=0;const a=await generateCourseAssignment(L,{notes:'Supplies bought on account. Purchase discounts reduce supplies cost under the gross method. Record payment and supplies used.',year:2026,month:9,depth:'focused'},{key:'test',fetcher:async()=>({ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(++calls===1?topicDraft():paymentDraft())}}]})})}),b={name:'Tommy Coffee',type:'Coffee shop'},choice=L.decisions.defaultChoice(a,b);choice.decision1={beans:2,cups:2,filters:2};let r={assignment:a,business:b,choice,scenario:L.expected(a,choice,b),stage:0,decidedMonths:[0],entries:{},first:{},advanced:false};const invoice=structuredClone(r.scenario.events[0]);assert.equal(invoice.document.items.length,3);r=changeRun(L,r,'advance',{});assert.equal(L.pendingDecision(r),1);assert.deepEqual(L.availableEvents(r).map(e=>e.id),['supplies-invoice']);assert.throws(()=>changeRun(L,r,'decide',{choice:{decision1:1}}),/current month/);r=changeRun(L,r,'decide',{choice:{decision2:12}});assert.deepEqual(r.scenario.events[0],invoice);let payment=r.scenario.events.find(e=>e.id==='supplier-payment');assert.equal(payment.date,'2026-09-12');assert.equal(payment.lines.find(x=>x.account==='Cash').credit,139.16);assert.equal(payment.lines.find(x=>x.account==='Supplies').credit,2.84);assert.ok(payment.document.fields.some(f=>f.value==='2026-09-12'));const late=changeRun(L,{...r,decidedStages:[0]},'decide',{choice:{decision2:20}});payment=late.scenario.events.find(e=>e.id==='supplier-payment');assert.equal(payment.date,'2026-09-20');assert.equal(payment.lines.find(x=>x.account==='Cash').credit,142);assert.equal(payment.lines.some(x=>x.account==='Supplies'),false);assert.deepEqual(late.scenario.events[0],invoice);const grade=L.grade(r);r=changeRun(L,r,'challenge',{join:true,profit:1e9,grade:100});assert.deepEqual(L.grade(r),grade);assert.equal(r.challenge,true);assert.equal(studentRun(L,r).businessResult.cash,businessResult(L,r).cash);assert.throws(()=>changeRun(L,r,'challenge',{join:'yes'}),/Choose/);assert.throws(()=>L.decisions.calculate('decision2<=12?fetch(1):0',{decision2:2}));const forged=structuredClone(a);forged.interactive.events[0].document.fields.push({label:'Future',value:'{{date:decision2}}'});assert.equal(L.decisions.valid(forged),false);});
