test('professor revision keeps extracted topics, passes the actual request to the writer, and returns a checked unpublished draft',async()=>{const original=await assignment(),{generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs');let calls=0;const revised=await generateCourseAssignment(L,{phase:'revise',currentDraft:original,notes:original.notes,request:'Explain how to choose the payment date and keep the purchase separate.',year:2026,month:9,timelineMode:'auto',depth:'focused'},{key:'test',fetcher:async(url,request)=>{calls++;const body=JSON.parse(request.body),user=JSON.parse(body.messages[1].content);assert.equal(user.instructorRequest,'Explain how to choose the payment date and keep the purchase separate.');assert.deepEqual(user.topics,original.teachingTopics);assert.ok(user.revision.currentScenario.events.length);assert.ok(body.response_format.json_schema.schema.properties.topicCoverage);const made=scenarioDraft();made.title='Choose when to pay';made.topicCoverage=[{topicIndex:0,eventIds:['supplies-invoice','supplier-payment','supplies-count']}];return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(made)}}]})};}});assert.equal(calls,1);assert.equal(revised.title,'Choose when to pay');assert.equal(revised.published,false);assert.notEqual(revised.id,original.id);assert.equal(L.checkAssignment(revised),true);assert.deepEqual(revised.teachingTopics,original.teachingTopics);assert.equal(original.title,'Stock your business');});
test('topic coverage requires at least three quarters of distinct topics and links to actual source records',async()=>{const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs');const topics={topics:[{name:'Credit purchases',principle:'Purchases on account create a liability.',method:'Record the purchase on delivery.'},{name:'Supplier payments',principle:'Payment settles a liability.',method:'Use the payment confirmation.'},{name:'Supplies used',principle:'Usage is an expense.',method:'Use a closing count.'},{name:'Future benefits',principle:'Unused supplies are assets.',method:'Retain unused supplies in the asset account.'}],sourceParagraphs:[0]};for(const coverage of [[{topicIndex:0,eventIds:['supplies-invoice']}],[{topicIndex:0,eventIds:['supplies-invoice']},{topicIndex:0,eventIds:['supplies-invoice']},{topicIndex:0,eventIds:['supplies-invoice']}],[{topicIndex:0,eventIds:['missing']},{topicIndex:1,eventIds:['supplier-payment']},{topicIndex:2,eventIds:['supplies-count']}],[{topicIndex:0,eventIds:['supplies-invoice']},{topicIndex:1,eventIds:['supplier-payment']},{topicIndex:2,eventIds:['supplies-count']}]]){const made=scenarioDraft();made.topicCoverage=coverage;const create=()=>generateCourseAssignment(L,{notes:'Credit purchases, supplier payments, unused supplies and a month-end count of supplies.',phase:'review',draft:topics,year:2026,month:9,depth:'focused'},{key:'test',fetcher:async(url,request)=>{const schema=JSON.parse(request.body).response_format.json_schema.schema;assert.equal(schema.properties.topicCoverage.minItems,3);return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(made)}}]})};}});if(new Set(coverage.map(x=>x.topicIndex)).size<3||coverage.some(x=>x.eventIds.includes('missing')))await assert.rejects(create,/coverage|too few/);else{const a=await create();assert.equal(a.topicCoverage.length,3);assert.equal(a.teachingTopics.length,4);}}});
test('older supplier-payment drafts get a separate date choice before starting, and started runs retain original work',async()=>{const {prepareGuidedAssignment,studentDefinition,studentRun}=await import('./supabase/functions/classroom/service.mjs'),a=await assignment(),old=structuredClone(a);old.interactive.controls=old.interactive.controls.filter(c=>c.kind!=='date');for(const c of old.interactive.controls){delete c.decisionStage;delete c.monthOffset;}delete old.interactive.events.find(e=>e.id==='supplier-payment').dateControl;old.interactive.events.find(e=>e.id==='supplier-payment').document.fields=old.interactive.events.find(e=>e.id==='supplier-payment').document.fields.filter(f=>!f.value.includes('{{date:')); const ready=prepareGuidedAssignment(old),c=ready.interactive.controls.at(-1);assert.equal(c.kind,'date');assert.equal(c.decisionStage,1);assert.equal(studentDefinition(old).interactive.controls.at(-1).kind,'date');assert.equal(old.interactive.controls.length,2);const b={name:'My coffee shop',type:'Coffee shop'},choice=L.decisions.defaultChoice(old,b),scenario=L.expected(old,choice,b),state={assignment:old,business:b,choice,scenario,stage:1,entries:{},first:{},advanced:false};assert.equal(studentRun(L,state).assignment.interactive.controls.length,2);assert.equal(L.pendingDecision(state),null);});
test('generation makes one targeted document repair for malformed item-list expressions without changing accounting',async()=>{const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs'),made=scenarioDraft(),count=made.events.find(e=>e.id==='supplies-count');count.document.fields.find(f=>f.label==='Supplies on hand at cost').value='{{basket:decision1*0.4}}';let calls=0;const a=await generateCourseAssignment(L,{notes:'Supplies purchases and supplier payments, with supplies used based on a closing count.',phase:'review',draft:topicDraft(),year:2026,month:9,depth:'focused'},{key:'test',fetcher:async(url,request)=>{calls++;const body=JSON.parse(request.body);if(calls===2){const input=JSON.parse(body.messages[1].content);assert.equal(input.documents[0].eventId,'supplies-count');assert.ok(body.messages[0].content.includes('NEVER arithmetic'));assert.deepEqual(input.documents[0].accountingContext,count.lines);}return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(calls===1?made:{documents:[{eventId:'supplies-count',fields:count.document.fields.map(f=>({...f,value:f.value.replace('{{basket:decision1*0.4}}','{{money:decision1*0.4}}')}))}]})}}]})};}});assert.equal(calls,2);assert.deepEqual(a.interactive.events.find(e=>e.id==='supplies-count').lines,count.lines);assert.equal(L.checkAssignment(a),true);const b={name:'My coffee shop',type:'Coffee shop'},choice=L.decisions.defaultChoice(a,b);choice.decision1={beans:2,cups:2,filters:2};const s=L.expected(a,choice,b);assert.ok(s.events.find(e=>e.id==='supplies-count').document.fields.some(f=>f.value==='$56.80'));});
