test('orders affect customer activity and cash sales are balanced, visible, and excluded from the lesson grade',async()=>{const a=await assignment(),b={name:'Tommy Coffee',type:'Coffee shop'},small=L.decisions.defaultChoice(a,b),large=structuredClone(small);small.decision1={beans:1,cups:1,filters:1};large.decision1={beans:5,cups:5,filters:5};const low=L.expected(a,small,b),high=L.expected(a,large,b);assert.ok(high.operations[0].customers>low.operations[0].customers);assert.ok(high.operations[0].revenue>low.operations[0].revenue);assert.ok(high.operations[0].customers<=high.operations[0].demand);const report=high.events.find(e=>e.autoPosted);assert.ok(report);assert.equal(report.document.layout,'sales');assert.equal(report.lines[0].debit,high.operations[0].revenue);assert.equal(report.lines[0].debit,report.lines[1].credit);const r={assignment:a,business:b,choice:large,scenario:high,stage:0,decidedStages:[0],entries:{},first:{}};L.syncBusinessEntries(r);assert.equal(r.entries[report.id],undefined);r.stage=2;r.decidedStages=[0,1];L.syncBusinessEntries(r);assert.equal(r.entries[report.id].rows[0].debit,high.operations[0].revenue);assert.equal(L.grade(r).journal,0);for(const e of high.events.filter(e=>!e.autoPosted))r.entries[e.id]={date:e.date,rows:e.lines};assert.equal(L.grade(r).journal,100);assert.ok(Math.abs(Object.values(L.balances(high,r.entries)).reduce((n,x)=>n+x,0))<.01);});
