test('an AI payment percentage cannot masquerade as the payment date',async()=>{const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs'),made=scenarioDraft();made.events[1].dateControl='decision2';const a=await generateCourseAssignment(L,{notes:'Supplies purchases, supplier payments and supplies used.',phase:'review',draft:topicDraft(),year:2026,month:9,depth:'focused'},{key:'test',fetcher:async()=>({ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(made)}}]})})});const payment=a.interactive.events.find(e=>e.id==='supplier-payment');assert.notEqual(payment.dateControl,'decision2');assert.equal(a.interactive.controls.find(c=>c.id===payment.dateControl).kind,'date');assert.equal(a.interactive.controls.find(c=>c.id==='decision2').kind,'number');assert.ok(L.checkAssignment(a));});

test('basic transaction and classification practice is not stretched into artificial adjustment months',async()=>{const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs'),f=require('./test-fixtures/chapter-two-practice.cjs'),topics=f.topics();topics.timeline={startMonth:9,months:3,reason:'Several transactions.'};const a=await generateCourseAssignment(L,{notes:f.notes,phase:'review',draft:topics,year:2026,month:9,timelineMode:'auto',depth:'standard'},{key:'test',fetcher:async(url,request)=>{assert.equal(JSON.parse(JSON.parse(request.body).messages[1].content).assignmentPeriod.months,1);return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(f.scenario())}}]})};}});assert.equal(a.periodMonths,1);assert.ok(L.checkAssignment(a));});
test('all introductory account choices stay available on old runs and wrong choices receive feedback without corrupting balances',async()=>{const a=await assignment(),b={name:'My Coffee',type:'Coffee shop'},choice=L.decisions.defaultChoice(a,b),scenario=L.expected(a,choice,b);scenario.accountList=a.blueprint.accounts.map(x=>x.name);scenario.accountDefinitions=a.blueprint.accounts;const old={assignment:a,business:b,choice,scenario,stage:0,decidedStages:[0],entries:{},first:{},advanced:false,completed:false},{studentRun,changeRun}=await import('./supabase/functions/classroom/service.mjs'),pub=studentRun(L,old);for(const name of ['Supplies','Supplies Expense','Rent Expense','Equipment','Accounts Receivable','Inventory'])assert.ok(pub.scenario.accountList.includes(name));const e=scenario.events[0],wrong=changeRun(L,old,'entry',{record:e.id,date:e.date,rows:[{account:'Rent Expense',debit:e.lines[0].debit,credit:0},{account:'Accounts Payable',debit:0,credit:e.lines[0].debit}]});assert.equal(studentRun(L,wrong).assessments[e.id].correct,false);assert.ok(Object.values(L.balances(wrong.scenario,wrong.entries)).every(Number.isFinite));assert.equal(L.trialBalance(wrong.scenario,wrong.entries).balanced,true);const corrected=changeRun(L,wrong,'entry',{record:e.id,date:e.date,rows:e.lines});assert.equal(studentRun(L,corrected).assessments[e.id].correct,true);assert.deepEqual(old.entries,{});});
test('supply planning uses the student business, pack sizes and legal quantity bounds',()=>{for(const type of ['Coffee shop','Cleaning service']){const c={category:'supplies',min:0,max:30,step:1},g=L.decisions.orderGuidance(c,{type});assert.ok(g.demand>0&&g.budget>0);assert.ok(g.recommended>=c.min&&g.recommended<=c.max);assert.equal(g.items.length,3);assert.ok(g.items.every(x=>x.unit));assert.equal(g.budget,g.recommended*g.items.reduce((n,x)=>n+x.price,0));}const limited=L.decisions.orderGuidance({category:'supplies',min:0,max:1,step:1},{type:'Coffee shop'});assert.equal(limited.recommended,1);});
test('customer revenue taught in the notes cannot be replaced by background automatic sales',async()=>{const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs'),f=require('./test-fixtures/chapter-two-practice.cjs'),bad=f.scenario();bad.events.find(e=>e.id==='customer-payment').lines=[];let calls=0;const a=await generateCourseAssignment(L,{notes:f.notes,phase:'review',draft:f.topics(),year:2026,month:9,depth:'standard'},{key:'test',fetcher:async(url,request)=>{calls++;if(calls===2)assert.ok(JSON.parse(JSON.parse(request.body).messages[1].content).problems.some(x=>x.includes('earned customer revenue')));return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(calls===1?bad:f.scenario())}}]})};}});assert.equal(calls,2);assert.ok(a.interactive.events.some(e=>e.lines.some(l=>l.account==='Service Revenue')));});
test('grouped transaction principles still require earned customer revenue practice',async()=>{const {generateCourseAssignment}=await import('./supabase/functions/classroom/generator.mjs'),f=require('./test-fixtures/chapter-two-practice.cjs'),bad=f.scenario(),draft=f.topics();draft.topics[2]={...draft.topics[2],name:'Journalizing basic business transactions',principle:'Receiving cash for services already provided records earned revenue.'};bad.events.find(e=>e.id==='customer-payment').lines=[];let calls=0;const a=await generateCourseAssignment(L,{notes:f.notes,phase:'review',draft,year:2026,month:9,depth:'standard'},{key:'test',fetcher:async(url,request)=>{calls++;if(calls===2)assert.ok(JSON.parse(JSON.parse(request.body).messages[1].content).problems.some(x=>x.includes('earned customer revenue')));return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:JSON.stringify(calls===1?bad:f.scenario())}}]})};}});assert.equal(calls,2);assert.ok(a.interactive.events.some(e=>e.lines.some(l=>l.account==='Service Revenue')));});

test('saved count submissions are checked against the printed consumption cost, not an inconsistent old key',async()=>{
 const a=L.enableSimulation(await assignment()),{changeRun,studentRun}=await import('./supabase/functions/classroom/service.mjs'),business={name:"Tommy's Coffee",type:'Coffee shop'},choice=L.decisions.defaultChoice(a,business);choice.decision1={beans:10,cups:8,filters:10};
 const scenario=L.expected(a,choice,business),e=scenario.events.find(e=>e.id==='supplies-count');
 e.document.fields.push({label:'Supplies used during month (cost)',value:'$404.40'});e.detail.document=e.document;
 e.lines=[{account:'Supplies',debit:404.4,credit:0},{account:'Cash',debit:0,credit:404.4}];
 const state={assignment:a,business,choice,scenario,stage:2,advanced:true,entries:{},first:{}},rows=[{account:'Supplies Expense',debit:404.4,credit:0},{account:'Supplies',debit:0,credit:404.4}];
 const saved=changeRun(L,state,'entry',{record:e.id,date:e.date,rows});assert.equal(studentRun(L,saved).assessments[e.id].correct,true);assert.equal(saved.first[e.id].correct,true);
 const wrong=changeRun(L,state,'entry',{record:e.id,date:e.date,rows:e.lines});assert.equal(studentRun(L,wrong).assessments[e.id].correct,false);
});

test('an old AI trial-balance event cannot create money, cost points, or prevent completion',async()=>{
 const a=L.enableSimulation(await assignment()),{changeRun,studentRun,businessResult}=await import('./supabase/functions/classroom/service.mjs'),business={name:"Tommy's Coffee",type:'Coffee shop'},choice=L.decisions.defaultChoice(a,business),before=L.expected(a,choice,business);
 a.interactive.events.push({id:'evt5',title:'Trial Balance Prepared',date:'2026-09-30',stage:2,document:{layout:'schedule',issuer:'{{business}}',status:'CONFIRMED',fields:[{label:'Trial balance includes all balances after journal entries',value:''},{label:'Debits and credits should match',value:''},{label:'Check Cash and Supplies totals',value:''}]},lines:[{account:'Cash',side:'debit',formula:'500'},{account:'Sales Revenue',side:'credit',formula:'500'}]});
 const scenario=L.expected(a,choice,business);assert.ok(!scenario.events.some(e=>e.id==='evt5'));assert.deepEqual(scenario.operations,before.operations);
 const entries=Object.fromEntries(scenario.events.map(e=>[e.id,{date:e.date,rows:e.lines}])),state={assignment:a,business,choice,scenario,stage:2,advanced:true,entries,first:{}};
 const completed=changeRun(L,state,'complete',{});assert.equal(completed.completed,true);assert.equal(studentRun(L,completed).serverGrade.journal,100);assert.equal(businessResult(L,completed).cash,businessResult(L,{...state,assignment:{...a,interactive:{...a.interactive,events:a.interactive.events.filter(e=>e.id!=='evt5')}},scenario:before}).cash);
 assert.throws(()=>changeRun(L,state,'entry',{record:'evt5',date:'2026-09-30',rows:[]}),/not available/);
});
